## Advanced Features

### RestClient Builder Configuration

```java
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.web.client.RestClient;

@Configuration
public class RestClientConfig {

    @Bean
    public RestClient restClient() {
        return RestClient.builder()
            .baseUrl("https://api.example.com")
            .defaultHeader("User-Agent", "MyApp/1.0")
            .defaultHeader("Accept", "application/json")
            .requestInterceptor(loggingInterceptor())
            .build();
    }

    private ClientHttpRequestInterceptor loggingInterceptor() {
        return (request, body, execution) -> {
            System.out.println("Request: " + request.getMethod() + " " + request.getURI());
            return execution.execute(request, body);
        };
    }
}
```

### Error Handling

#### Before (RestTemplate)
```java
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestTemplate;

public User getUserSafely(Long id) {
    RestTemplate restTemplate = new RestTemplate();
    try {
        return restTemplate.getForObject(
            "https://api.example.com/users/" + id,
            User.class
        );
    } catch (HttpClientErrorException.NotFound e) {
        return null;
    } catch (HttpClientErrorException e) {
        throw new RuntimeException("API error: " + e.getStatusCode());
    }
}
```

#### After (RestClient)
```java
import org.springframework.http.HttpStatusCode;
import org.springframework.web.client.RestClient;

public User getUserSafely(Long id) {
    RestClient restClient = RestClient.create();

    return restClient.get()
        .uri("https://api.example.com/users/{id}", id)
        .retrieve()
        .onStatus(HttpStatusCode::is4xxClientError, (request, response) -> {
            if (response.getStatusCode().value() == 404) {
                // Return null for not found
                return;
            }
            throw new RuntimeException("Client error: " + response.getStatusCode());
        })
        .onStatus(HttpStatusCode::is5xxServerError, (request, response) -> {
            throw new RuntimeException("Server error: " + response.getStatusCode());
        })
        .body(User.class);
}
```

## Complete Service Migration Example

### Before (RestTemplate)
```java
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.*;
import java.util.Map;

@Service
public class ExternalApiService {

    private final RestTemplate restTemplate;
    private final String baseUrl = "https://api.example.com";

    public ExternalApiService() {
        this.restTemplate = new RestTemplate();
    }

    public boolean verifyEmail(String email) {
        try {
            String url = baseUrl + "/verify/email?email=" + email;
            ResponseEntity<Map> response = restTemplate.getForEntity(url, Map.class);
            return Boolean.TRUE.equals(response.getBody().get("valid"));
        } catch (Exception e) {
            return false;
        }
    }

    public void sendNotification(String userId, String message) {
        try {
            String url = baseUrl + "/notifications";

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);

            Map<String, String> payload = Map.of(
                "userId", userId,
                "message", message
            );

            HttpEntity<Map<String, String>> request = new HttpEntity<>(payload, headers);
            restTemplate.postForEntity(url, request, Void.class);
        } catch (Exception e) {
            System.err.println("Failed to send notification: " + e.getMessage());
        }
    }
}
```

### After (RestClient)
```java
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import org.springframework.http.MediaType;
import java.util.Map;

@Service
public class ExternalApiService {

    private final RestClient restClient;

    public ExternalApiService() {
        this.restClient = RestClient.builder()
            .baseUrl("https://api.example.com")
            .build();
    }

    public boolean verifyEmail(String email) {
        try {
            Map<String, Object> response = restClient.get()
                .uri("/verify/email?email={email}", email)
                .retrieve()
                .body(Map.class);

            return response != null && Boolean.TRUE.equals(response.get("valid"));
        } catch (Exception e) {
            return false;
        }
    }

    public void sendNotification(String userId, String message) {
        try {
            Map<String, String> payload = Map.of(
                "userId", userId,
                "message", message
            );

            restClient.post()
                .uri("/notifications")
                .contentType(MediaType.APPLICATION_JSON)
                .body(payload)
                .retrieve()
                .toBodilessEntity();
        } catch (Exception e) {
            System.err.println("Failed to send notification: " + e.getMessage());
        }
    }
}
```

## Migration Checklist

- [ ] Replace `new RestTemplate()` with `RestClient.create()` or builder
- [ ] Replace `getForObject()` with `.get().uri().retrieve().body()`
- [ ] Replace `getForEntity()` with `.get().uri().retrieve().toEntity()`
- [ ] Replace `postForObject()` with `.post().uri().body().retrieve().body()`
- [ ] Replace `postForEntity()` with `.post().uri().body().retrieve().toEntity()`
- [ ] Replace `exchange()` with appropriate HTTP method + `.retrieve()`
- [ ] Replace `delete()` with `.delete().uri().retrieve().toBodilessEntity()`
- [ ] Update error handling from try-catch to `.onStatus()`
- [ ] Use URI templates instead of string concatenation
- [ ] Configure base URL in builder if used repeatedly

## Best Practices

1. **Use Builder for Configuration**: Create a configured `RestClient` bean
2. **URI Templates**: Use URI templates instead of string concatenation
3. **Base URL**: Configure base URL once in the builder
4. **Error Handling**: Use `.onStatus()` for structured error handling
5. **Dependency Injection**: Inject configured `RestClient` beans

