### 5. JPQL Queries

JPQL queries remain largely compatible:

```java
import jakarta.persistence.EntityManager;
import jakarta.persistence.TypedQuery;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public class CustomUserRepository {

    private final EntityManager entityManager;

    public CustomUserRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    public List<User> findActiveUsers() {
        String jpql = "SELECT u FROM User u WHERE u.active = true";
        TypedQuery<User> query = entityManager.createQuery(jpql, User.class);
        return query.getResultList();
    }

    public List<User> searchUsers(String keyword) {
        String jpql = "SELECT u FROM User u WHERE " +
                     "LOWER(u.username) LIKE LOWER(:keyword) OR " +
                     "LOWER(u.email) LIKE LOWER(:keyword)";
        TypedQuery<User> query = entityManager.createQuery(jpql, User.class);
        query.setParameter("keyword", "%" + keyword + "%");
        return query.getResultList();
    }
}
```

